from typing import List

class Solution:
    def maxProduct(self, nums: List[int]) -> int:
        best = nums[0]

        def extend(start: int, end: int, product: int) -> None:
            nonlocal best
            if end == len(nums):
                return
            product *= nums[end]
            best = max(best, product)
            extend(start, end + 1, product)

        for i in range(len(nums)):
            extend(i, i, 1)
        return best

