from typing import List

class Solution:
    def maxProduct(self, nums: List[int]) -> int:
        cur_max = cur_min = ans = nums[0]
        for x in nums[1:]:
            a, b = x * cur_max, x * cur_min
            cur_max = max(x, a, b)
            cur_min = min(x, a, b)
            ans = max(ans, cur_max)
        return ans

